def sliding_window_list(lst, k):
    n = len(lst)
    if not isinstance(k, int) or k <= 0 or k > n:
        return []
    windows = []
    for start in range(n - k + 1):
        windows.append(lst[start:start + k])
    return windows

def nested_group_counts(pairs):
    result = {}
    for group, item in pairs:
        if group not in result:
            result[group] = {}
        result[group][item] = result[group].get(item, 0) + 1
    return result

