def alternate_upper_lower(s):
    result = []
    letter_index = 0
    for ch in s:
        if ch.isalpha():
            if letter_index % 2 == 0:
                result.append(ch.upper())
            else:
                result.append(ch.lower())
            letter_index += 1
        else:
            result.append(ch)
    return ''.join(result)

