def smallest_repeating_unit(s):
    n = len(s)
    if n == 0:
        return ''
    for length in range(1, n):
        if n % length != 0:
            continue
        unit = s[:length]
        repeats = n // length
        if unit * repeats == s:
            return unit
    return s

def is_valid_query_string(s):
    if not s.startswith('?') or len(s) == 1:
        return False
    pairs = s[1:].split('&')
    for pair in pairs:
        parts = pair.split('=')
        if len(parts) != 2:
            return False
        key, value = parts
        if not key or not value:
            return False
        if not key.isalnum() or not value.isalnum():
            return False
    return True

