def center_moving_average(lst, radius):
    n = len(lst)
    if n == 0:
        return []
    result = []
    for i in range(n):
        start = max(0, i - radius)
        end = min(n - 1, i + radius)
        window = lst[start:end + 1]
        result.append(round(sum(window) / len(window)))
    return result

